function stRenderCurve(id){
 const markets=EC.borrow_markets.filter(m=>m.rate_model?.points?.length),m=markets.find(m=>m.id===id)||markets[0];stCurve=m.id;
 $('#strict-curve-controls').innerHTML=markets.map(row=>`<button class="btn" data-strict-curve="${esc(row.id)}" aria-pressed="${row.id===m.id}">${esc(document.body.dataset.edition==='reader'?row.venue.replace(' Blue','')+' '+(row.loan_symbol==='USDC'&&['arbitrum','optimism'].includes(row.chain)?'USDCn':row.loan_symbol)+' · '+row.chain:row.venue+' '+row.collateral_symbol+'/'+row.loan_symbol+' · '+row.chain)}</button>`).join('');
 const points=m.rate_model.points,W=innerWidth<560?420:720,H=300,P={l:76,r:32,t:22,b:48},max=chartNice(Math.max(...points.map(p=>p.borrow_apr),m.borrow_apr||0)),x=v=>P.l+v*(W-P.l-P.r),y=v=>P.t+(1-v/max)*(H-P.t-P.b);
 let svg=`<svg class="line-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(m.venue+' '+m.loan_symbol+' borrowing APR at different utilization')}" ><title>${esc(m.rate_model.name)}: utilization and borrowing APR</title>`;
 for(let i=0;i<=4;i++){let v=max*i/4;svg+=`<line x1="${P.l}" x2="${W-P.r}" y1="${y(v)}" y2="${y(v)}" stroke="var(--grid)"/><text x="${P.l-12}" y="${y(v)+4}" text-anchor="end" fill="var(--muted)" font-size="11" font-family="var(--mono)">${pct(v,1)}</text>`;}
 for(let i=0;i<=5;i++)svg+=`<text x="${x(i/5)}" y="${H-17}" text-anchor="middle" fill="var(--muted)" font-size="11" font-family="var(--mono)">${pct(i/5,0)}</text>`;
 svg+=`<path d="${points.map((p,i)=>(i?'L':'M')+x(p.utilization)+','+y(p.borrow_apr)).join(' ')}" fill="none" stroke="var(--accent)" stroke-width="3"/>`;
 points.forEach((point,i)=>{
  const left=i?(x(points[i-1].utilization)+x(point.utilization))/2:P.l,right=i<points.length-1?(x(point.utilization)+x(points[i+1].utilization))/2:W-P.r;
  const title=m.venue+' / '+m.loan_symbol,rows=[{name:'Utilization',value:pct(point.utilization,1),color:'var(--accent)'},{name:'Borrow APR',value:pct(point.borrow_apr,3),color:'var(--accent)'}],note=title+' · '+pct(point.utilization,1)+' utilization · '+pct(point.borrow_apr,3)+' APR';
  svg+=`<rect class="chart-month-hit" tabindex="${i===0?0:-1}" x="${left}" y="${P.t}" width="${right-left}" height="${H-P.t-P.b}" fill="transparent" data-chart-tip="${esc(note)}" data-chart-title="${esc(title)}" data-chart-rows="${esc(JSON.stringify(rows))}" data-strict-point="${esc(note)}" aria-label="${esc(note)}"/>`;
 });
 if(m.utilization!=null&&m.borrow_apr!=null){const rows=[{name:'Utilization diagnostic',value:pct(m.utilization,2),color:'var(--s4)'},{name:'Stored borrow APR',value:pct(m.borrow_apr,4),color:'var(--s4)'}];svg+=`<circle tabindex="0" cx="${x(m.utilization)}" cy="${y(m.borrow_apr)}" r="6" fill="var(--s4)" data-chart-title="Stored observation at T" data-chart-rows="${esc(JSON.stringify(rows))}" data-chart-tip="Observed stored rate at T: ${pct(m.borrow_apr,4)} APR; utilization diagnostic ${pct(m.utilization,2)}" aria-label="Observed stored rate at T: ${pct(m.borrow_apr,4)} APR; utilization diagnostic ${pct(m.utilization,2)}"/>`;}
 $('#strict-curve-chart').innerHTML=svg+'</svg><div id="strict-curve-tooltip" class="chart-tooltip" aria-live="polite">Focus or hover on a point to inspect the rate.</div><p class="sub">Horizontal: utilization. Vertical: borrowing APR. Gold point: stored market observation at T.</p>';
 $('#strict-curve-table').innerHTML=stTable(['Utilization','Borrow APR','Annual equivalent'],points.map(p=>[pct(p.utilization,1),pct(p.borrow_apr,4),pct(p.borrow_apy,4)]));
 $('#strict-curve-note').innerHTML=esc(m.rate_model.name)+': '+esc(m.rate_model.verification)+'. '+esc(m.rate_model.curve_basis)+' '+esc(m.utilization_basis||'')+' '+stSources(Object.values(m.links||{}).map(url=>({url,label:'Market / contract'})));
 if(document.body.dataset.edition==='reader')$('#strict-curve-note').innerHTML='Stored rate-model parameters at T, varying utilization. <a href="library/CARRY-MATH.html">Contract and model verification →</a>';
}
